let snappy_compress_check_vector line =
  match String.split_on_char ' ' line with
    [lv; inp; outp] ->
      let l = snappy_mk_bytelist(snappy_hex_bytes inp) in
      let r = rand(concl(SNAPPY_COMPRESS_EVAL_CONV
                (list_mk_comb(`snappy_compress`,
                              [mk_small_numeral(int_of_string lv); l])))) in
      r = snappy_mk_bytelist(snappy_hex_bytes outp)
  | _ -> failwith "snappy_compress_check_vector: bad line";;

let snappy_compress_test_failures =
  filter (fun l -> not(snappy_compress_check_vector l))
         snappy_compress_test_vectors;;

Printf.printf "snappy_compress tests: %d vectors, %d failures\n%!"
  (length snappy_compress_test_vectors)
  (length snappy_compress_test_failures);;

List.iter (Printf.printf "FAILED VECTOR: %s\n%!") snappy_compress_test_failures;;

if snappy_compress_test_failures <> [] then
  failwith "snappy_compress tests failed";;
